-- *_weekly_areas 데이터 업그레이드 리허설 — 구분 문자열을 가진 주간 행이 든 DB 를 만든다. 직전 마이그레이션까지 적용한 DB 에 흘리고 **커밋**한다.
-- 명령 전문은 SP4 Phase A1 계획 과제 14 Step 9(전용 스택, 공유 잠금 안). 순서:
--   supabase db reset --version <직전 번호> → 이 파일 → supabase migration up --local → *_weekly_areas_smoke.sql
--   → *_weekly_areas_created_fixture.sql → (뒤 SP4 파일 *_command_receipts·*_authz_carry 가 적용돼 있으면 그 롤백을 역순으로 먼저)
--   → *_weekly_areas_rollback.sql → *_weekly_areas_rollback_check.sql → 마이그레이션 재적용(psql -1) → *_weekly_areas_smoke.sql
-- 덮는 경우(스펙 §3.6): 자유 텍스트 구분, 중복 (문서, 구분)(두 행 모두 내용), 앞뒤 공백 구분, 구분 아래 모듈 행(머리표 줄 — 병합 묶음과
-- 행 하나짜리 묶음), 번호 목록 칸 + 머리표(병합 묶음·행 하나짜리 묶음 — 이관 뒤 점검이 구획마다 1부터 읽는다), 모듈 = 구분인 행(머리표
-- 없음), 빈 구분 + 모듈(→ 모듈 이름 영역, 머리표 없음), 둘 다 빈 행(→ '기타'), 공백뿐인 칸(다듬지 않고 옮긴다 — 모듈 행이어도 머리표
-- 없음, 탭·NBSP 뿐인 칸 포함), 주간행 없는 프로젝트의 기존 영역, 라벨과 code 가 같은 기존 영역(재사용), 비활성 기존 영역의 재사용,
-- 병합 길이(머리표 포함)가 상한과 같은 칸, [RF1] 구분·모듈 앞뒤의 NBSP·U+3000·BOM.
-- 뒤 두 파일(*_command_receipts·*_authz_carry)의 리허설도 이 시드가 남은 상태에서 돈다 — 상속 프로젝트 P3(공용 팀으로 꾸린 명단·담당·
-- 영역 팀·수락 전 초대)와 계정 둘·인물 셋·설정 행이 그 몫이다. 계정은 로그인하지 않는다(비밀번호 없음).
-- uuid 넷째 묶음 5b04(사전검사 파일은 다섯째 묶음 9xxx).
begin;
insert into auth.users (id, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, aud, role, instance_id, created_at, updated_at)
select v.id, v.email, '', now(), '{"provider":"email","providers":["email"]}', '{}', 'authenticated', 'authenticated',
       '00000000-0000-0000-0000-000000000000', now(), now()
  from (values
    ('00000000-0000-0000-5b04-000000005001'::uuid, 'sp4-wa-admin@example.com'),     -- u1 — W1 관리자
    ('00000000-0000-0000-5b04-000000005002'::uuid, 'sp4-wa-member@example.com')     -- u2 — W1 멤버, P3 명단 member
  ) as v(id, email);
