  ('00000000-0000-0000-5b04-000000002002', '00000000-0000-0000-5b04-000000000c01', 'weekly_section', '보류', '보류 영역', 7, false),  -- E2: 비활성 → 재사용(비활성 그대로)
  ('00000000-0000-0000-5b04-000000002003', '00000000-0000-0000-5b04-000000000c02', 'weekly_section', '운영', '운영 영역', 1, true),   -- E3: 주간행 없는 프로젝트 → 그대로
